INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea887fed-ce2f-5858-954a-bd74c054f295', 'Chile Public Procurement Directive', 'Public Procurement Directive No. 25', 'The Procurement Directives are general guidelines and recommendations, prepared by the ChileCompra Directorate. These good practices, which are disseminated through the directives, favor better management of purchasing processes, within the current legal framework and Government policies on the matter. They are intended to encourage and enhance the performance of contracting procedures.', 'The Procurement Directives are general guidelines and recommendations, prepared by the ChileCompra Directorate. These good practices, which are disseminated through the directives, favor better management of purchasing processes, within the current legal framework and Government policies on the matter. They are intended to encourage and enhance the performance of contracting procedures.', 'The Procurement Directives are general guidelines and recommendations, prepared by the ChileCompra Directorate. These good practices, which are disseminated through the directives, favor better management of purchasing processes, within the current legal framework and Government policies on the matter. They are intended to encourage and enhance the performance of contracting procedures.', 'Chile', 'climate', 'in_force', '2016-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_3', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'chile', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fc4edf2b-91b1-5546-86ec-3fc0777ce9de', 'Chile Manual of the Municipal Environmental Certification System', 'Manual of the Municipal Environmental Certification System', 'This manual supports, precisely, the certification process of the municipalities, delivering in a practical and detailed way, each one of the steps and key elements to achieve the basic, intermediate and excellence levels of environmental certification.', 'This manual supports, precisely, the certification process of the municipalities, delivering in a practical and detailed way, each one of the steps and key elements to achieve the basic, intermediate and excellence levels of environmental certification.', 'This manual supports, precisely, the certification process of the municipalities, delivering in a practical and detailed way, each one of the steps and key elements to achieve the basic, intermediate and excellence levels of environmental certification.', 'Chile', 'climate', 'in_force', '2016-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_42', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'chile']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa0f29d9-a599-5c05-bdb0-0e34c627c8fc', 'Chile Preparation of an Institutional Educational Project (PEI)', 'Guidelines for the Preparation of an Institutional Educational Project (PEI) from Environmental Education', 'The Ministry of the Environment has launched a program to encourage educational establishments to promote and incorporate environmental education in their daily work. The document that is made available to teachers and directors follows the same line, but emphasizes the creation of an Institutional Educational Project (PEI) with an environmental seal. President Bachelet''s program reiterates the need to reinforce "environmental education content both in formal education programs at different levels, as well as in training and awareness for different sectors and groups".', 'The Ministry of the Environment has launched a program to encourage educational establishments to promote and incorporate environmental education in their daily work. The document that is made available to teachers and directors follows the same line, but emphasizes the creation of an Institutional Educational Project (PEI) with an environmental seal. President Bachelet''s program reiterates the need to reinforce "environmental education content both in formal education programs at different levels, as well as in training and awareness for different sectors and groups".', 'The Ministry of the Environment has launched a program to encourage educational establishments to promote and incorporate environmental education in their daily work. The document that is made available to teachers and directors follows the same line, but emphasizes the creation of an Institutional Educational Project (PEI) with an environmental seal. President Bachelet''s program reiterates the need to reinforce "environmental education content both in formal education programs at different levels, as well as in training and awareness for different sectors and groups".', 'Chile', 'climate', 'in_force', '2015-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_46', ARRAY['sdg4', 'guidance_frameworks', 'sdg14', 'other sustainability policy', 'sdg7', 'chile', 'sdg12', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('37b07e15-4780-5ee8-b6ce-247dfffae25c', 'Chile Responsible Gaming Code of Conduct', 'Responsible Gaming Code of Conduct', 'The Chilean Association of Gaming Casinos and our associated companies are committed to working to promote Responsible Gaming throughout Chile. We understand Responsible Gaming to be the promotion of behavior patterns in players that minimize the risk of addiction, making it possible for this to be an entertainment activity. This Code of Conduct contains precisely these practices that we want to promote as an Association, which will be added to the existing regulations so that they become an integral part of the operations of the associated companies and the actions of their workers.', 'The Chilean Association of Gaming Casinos and our associated companies are committed to working to promote Responsible Gaming throughout Chile. We understand Responsible Gaming to be the promotion of behavior patterns in players that minimize the risk of addiction, making it possible for this to be an entertainment activity. This Code of Conduct contains precisely these practices that we want to promote as an Association, which will be added to the existing regulations so that they become an integral part of the operations of the associated companies and the actions of their workers.', 'The Chilean Association of Gaming Casinos and our associated companies are committed to working to promote Responsible Gaming throughout Chile. We understand Responsible Gaming to be the promotion of behavior patterns in players that minimize the risk of addiction, making it possible for this to be an entertainment activity. This Code of Conduct contains precisely these practices that we want to promote as an Association, which will be added to the existing regulations so that they become an integral part of the operations of the associated companies and the actions of their workers.', 'Chile', 'nature', 'in_force', '2015-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_49', ARRAY['guidance_frameworks', 'sdg8', 'other sustainability policy', 'mandatory', 'chile']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d54dd244-bb3d-5d21-b4df-7133090d51e9', 'Chile General Standard', 'General Standard No. 385', 'Publicly traded companies must submit to this Superintendence the information regarding their corporate governance, social responsibility and sustainable development practices referred to in the Annex to this regulation.', 'Publicly traded companies must submit to this Superintendence the information regarding their corporate governance, social responsibility and sustainable development practices referred to in the Annex to this regulation.', 'Publicly traded companies must submit to this Superintendence the information regarding their corporate governance, social responsibility and sustainable development practices referred to in the Annex to this regulation.', 'Chile', 'governance', 'in_force', '2015-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_6', ARRAY['voluntary_frameworks', 'sdg16', 'chile', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e1ca001-edef-59f7-8d60-9579efbafc8b', 'Chile General Standard', 'General Standard No. 386', 'This amendment requires companies to comply with additional reporting requirements on gender and diversity. It includes: diversity on the board (number of members by gender, age, nationality, duration in company), diversity in management (same aspects), diversity in the organization (idem), and wage difference per gender.', 'This amendment requires companies to comply with additional reporting requirements on gender and diversity. It includes: diversity on the board (number of members by gender, age, nationality, duration in company), diversity in management (same aspects), diversity in the organization (idem), and wage difference per gender.', 'This amendment requires companies to comply with additional reporting requirements on gender and diversity. It includes: diversity on the board (number of members by gender, age, nationality, duration in company), diversity in management (same aspects), diversity in the organization (idem), and wage difference per gender.', 'Chile', 'climate', 'in_force', '2015-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_7', ARRAY['sdg10', 'voluntary', 'sdg5', 'sdg16', 'chile', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fddfa666-00ef-5f74-8500-bac693c66cd8', 'Chile Guide for the prevention of workplace harassment aimed', 'Guide for the prevention of workplace harassment aimed at workers in the public sector, from a gender perspective', 'Chilean guide aims to report on the reality of workplace harassment in the Chilean public administration from a gender perspective, since public officials are the ones who suffer the most from this type of abuse. The guide contains two parts, the first around the identification of violence against women and the second regarding the magnitude and perception of such abuse.', 'Chilean guide aims to report on the reality of workplace harassment in the Chilean public administration from a gender perspective, since public officials are the ones who suffer the most from this type of abuse. The guide contains two parts, the first around the identification of violence against women and the second regarding the magnitude and perception of such abuse.', 'Chilean guide aims to report on the reality of workplace harassment in the Chilean public administration from a gender perspective, since public officials are the ones who suffer the most from this type of abuse. The guide contains two parts, the first around the identification of violence against women and the second regarding the magnitude and perception of such abuse.', 'Chile', 'climate', 'in_force', '2014-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_28', ARRAY['sdg8', 'other sustainability policy', 'mandatory', 'sdg5', 'chile', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2ca838fe-5d7e-5648-a9f7-0a89ca3d06f4', 'Chile How to include Environmental, Social and Corporate Governance', 'How to include Environmental, Social and Corporate Governance Factors: Design and Construction of Sustainability Reports, 2014', 'This guide provides insight into the benefits of ESG reporting for issuers, as well as guidance on navigating the reporting process so that they may effectively and credibly disclose ESG information to investors.', 'This guide provides insight into the benefits of ESG reporting for issuers, as well as guidance on navigating the reporting process so that they may effectively and credibly disclose ESG information to investors.', 'This guide provides insight into the benefits of ESG reporting for issuers, as well as guidance on navigating the reporting process so that they may effectively and credibly disclose ESG information to investors.', 'Chile', 'climate', 'in_force', '2014-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_56', ARRAY['regulations', 'sdg7', 'mandatory', 'chile', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9365f6ef-177f-52e2-8926-5b7363b88170', 'Indigenous Conservation Territories. Learning from practice in southern Chile', 'Indigenous Conservation Territories. Learning from practice in southern Chile', 'This publication is aimed at leaders of indigenous and local communities, representatives of governmental and non-governmental organizations, companies, and private individuals, in order to promote discussion about indigenous conservation initiatives and, above all, as a contribution to the conceptualization and constitution of Indigenous Conservation Territories.', 'This publication is aimed at leaders of indigenous and local communities, representatives of governmental and non-governmental organizations, companies, and private individuals, in order to promote discussion about indigenous conservation initiatives and, above all, as a contribution to the conceptualization and constitution of Indigenous Conservation Territories.', 'This publication is aimed at leaders of indigenous and local communities, representatives of governmental and non-governmental organizations, companies, and private individuals, in order to promote discussion about indigenous conservation initiatives and, above all, as a contribution to the conceptualization and constitution of Indigenous Conservation Territories.', 'Chile', 'climate', 'in_force', '2012-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_36', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'chile', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('542bfef6-b746-5d50-afc6-a5845500e450', 'Chile Planning and Management of Community Ecotourism with Indigenous', 'Planning and Management of Community Ecotourism with Indigenous Communities', 'In this document, indigenous community ecotourism is conceived as a complement to other more traditional economic activities, acting as a catalyst for the local economy by generating a supply of local products and services. This publication is a general guide for the development of ecotourism by indigenous communities, which must be applied and adapted to the reality and experience of each community with the particularities of each one and its territory.', 'In this document, indigenous community ecotourism is conceived as a complement to other more traditional economic activities, acting as a catalyst for the local economy by generating a supply of local products and services. This publication is a general guide for the development of ecotourism by indigenous communities, which must be applied and adapted to the reality and experience of each community with the particularities of each one and its territory.', 'In this document, indigenous community ecotourism is conceived as a complement to other more traditional economic activities, acting as a catalyst for the local economy by generating a supply of local products and services. This publication is a general guide for the development of ecotourism by indigenous communities, which must be applied and adapted to the reality and experience of each community with the particularities of each one and its territory.', 'Chile', 'nature', 'in_force', '2012-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_47', ARRAY['other sustainability policy', 'sdg11', 'mandatory', 'chile', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a58f98a7-9837-52dc-aa41-034341be52e3', 'Chile General Standard', 'General Standard No. 341', 'The objective of this measure is to provide adequate information to the investing public regarding the policies and practices of corporate governance adopted by open corporations, and to allow entities such as stock exchanges or study centers to generate their own analyzes. In addition, they make it easier for the various market players to know and evaluate the commitment of the companies with them.', 'The objective of this measure is to provide adequate information to the investing public regarding the policies and practices of corporate governance adopted by open corporations, and to allow entities such as stock exchanges or study centers to generate their own analyzes. In addition, they make it easier for the various market players to know and evaluate the commitment of the companies with them.', 'The objective of this measure is to provide adequate information to the investing public regarding the policies and practices of corporate governance adopted by open corporations, and to allow entities such as stock exchanges or study centers to generate their own analyzes. In addition, they make it easier for the various market players to know and evaluate the commitment of the companies with them.', 'Chile', 'governance', 'in_force', '2012-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_9', ARRAY['voluntary_frameworks', 'sdg16', 'chile', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a316816-145c-5b5e-aa3b-f093b01f5828', 'Chile Code of Good Practices in the Construction Industry', 'Code of Good Practices in the Construction Industry', 'A self-regulatory Code, called "Code of Good Practices in the Construction Industry", of general application, was approved by the Chilean Chamber of Construction on December 13, 2014. The document contains the requirements and actions that allow a good relationship between all parties involved in a construction project. The CChC will promote the execution of social projects through the entities that make up its Social Network. The Code should address, mainly, ethical aspects, also covering the following topics: care for the environment, the 67 relationship with the community and standards on quality and safety in the industry.', 'A self-regulatory Code, called "Code of Good Practices in the Construction Industry", of general application, was approved by the Chilean Chamber of Construction on December 13, 2014. The document contains the requirements and actions that allow a good relationship between all parties involved in a construction project. The CChC will promote the execution of social projects through the entities that make up its Social Network. The Code should address, mainly, ethical aspects, also covering the following topics: care for the environment, the 67 relationship with the community and standards on quality and safety in the industry.', 'A self-regulatory Code, called "Code of Good Practices in the Construction Industry", of general application, was approved by the Chilean Chamber of Construction on December 13, 2014. The document contains the requirements and actions that allow a good relationship between all parties involved in a construction project. The CChC will promote the execution of social projects through the entities that make up its Social Network. The Code should address, mainly, ethical aspects, also covering the following topics: care for the environment, the 67 relationship with the community and standards on quality and safety in the industry.', 'Chile', 'social', 'in_force', '2011-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_18', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'chile', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f76c718c-f912-5cff-bb98-7e2024433e53', 'Chile General Standard', 'General Standard No. 309', 'This standard establishes principles and good practices of adequate corporate governance and risk management and internal control systems in insurance companies. Although their implementation may adopt different modalities in the different companies, these principles and good practices will serve as the basis for the evaluation of the quality of corporate governance that the Superintendence will carry out, within the framework of the application of the new supervision model.', 'This standard establishes principles and good practices of adequate corporate governance and risk management and internal control systems in insurance companies. Although their implementation may adopt different modalities in the different companies, these principles and good practices will serve as the basis for the evaluation of the quality of corporate governance that the Superintendence will carry out, within the framework of the application of the new supervision model.', 'This standard establishes principles and good practices of adequate corporate governance and risk management and internal control systems in insurance companies. Although their implementation may adopt different modalities in the different companies, these principles and good practices will serve as the basis for the evaluation of the quality of corporate governance that the Superintendence will carry out, within the framework of the application of the new supervision model.', 'Chile', 'governance', 'in_force', '2011-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_48', ARRAY['voluntary_frameworks', 'sdg16', 'chile', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b2f3e8ff-3f1f-54f0-a5f8-8583710dd4ef', 'Chile Manual for Environmental Management in Educational Establishments: Waste', 'Manual for Environmental Management in Educational Establishments: Waste, Energy and Water', 'The present support material is oriented to the generation of friendly behaviors with the environment in the field of management of the educational establishment; delivering environmental procedures and practices that have been built from concrete experiences, observed in different schools in Chile. At the same time, it is an aid for compliance with the indicators established in the Management Area.', 'The present support material is oriented to the generation of friendly behaviors with the environment in the field of management of the educational establishment; delivering environmental procedures and practices that have been built from concrete experiences, observed in different schools in Chile. At the same time, it is an aid for compliance with the indicators established in the Management Area.', 'The present support material is oriented to the generation of friendly behaviors with the environment in the field of management of the educational establishment; delivering environmental procedures and practices that have been built from concrete experiences, observed in different schools in Chile. At the same time, it is an aid for compliance with the indicators established in the Management Area.', 'Chile', 'climate', 'in_force', '2006-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_37', ARRAY['sdg4', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'chile', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0f3d14d9-258a-5703-9b02-51d93260f602', 'Chile Environmental Practices Manual', 'Environmental Practices Manual', 'This guide includes the minimum practices that must be applied according to the specific environmental characteristics of the area in which the mining exploration activities are carried out. Its scope is intended only to complement the internal guidelines that each company defines for compliance with current legislation and that of its corporate environmental policies, including the requirements that these demand from contractor companies in exploration activities', 'This guide includes the minimum practices that must be applied according to the specific environmental characteristics of the area in which the mining exploration activities are carried out. Its scope is intended only to complement the internal guidelines that each company defines for compliance with current legislation and that of its corporate environmental policies, including the requirements that these demand from contractor companies in exploration activities', 'This guide includes the minimum practices that must be applied according to the specific environmental characteristics of the area in which the mining exploration activities are carried out. Its scope is intended only to complement the internal guidelines that each company defines for compliance with current legislation and that of its corporate environmental policies, including the requirements that these demand from contractor companies in exploration activities', 'Chile', 'climate', 'in_force', '1999-01-01'::date, 'Chile', 'https://www.carrotsandsticks.org/policies/32_40', ARRAY['chile', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2bf2f58-248a-5dbe-89fd-b0764ab61278', 'China High-Standard Social Responsibility for Central Enterprises (关于新时代中央企业高标准履行社会责任的指导意见)', 'Guidelines on High-Standard Social Responsibility for Central Enterprises (关于新时代中央企业高标准履行社会责任的指导意见)', 'Issued by the State-Owned Assets Supervision and Administration Commission (SASAC) on June 4, 2024, these guidelines provide a comprehensive framework for China’s central enterprises (央企) to integrate Environmental, Social, and Governance (ESG) principles into their corporate responsibility efforts. The guidelines emphasize high-standard social responsibility, economic leadership, and alignment with China’s sustainable development goals.

Key aspects include:

Mandating ESG Integration:
ESG principles are now a core requirement for central enterprises.
Listed subsidiaries must disclose ESG information to enhance transparency and meet international expectations.
Social Responsibility Expansion:
Focus on green development, technology innovation, and regional economic support.
Companies must improve corporate governance and supply chain sustainability.
ESG Disclosure & Market Leadership:
By 2025, central enterprises must establish a mature social responsibility system.
By 2030, these enterprises should be global leaders in sustainable business practices.
Regulatory Compliance & Reporting:
Central enterprises are required to publish social responsibility and ESG reports.
90.67% of listed central enterprises already disclose ESG reports, reflecting rapid adoption.', 'Issued by the State-Owned Assets Supervision and Administration Commission (SASAC) on June 4, 2024, these guidelines provide a comprehensive framework for China’s central enterprises (央企) to integrate Environmental, Social, and Governance (ESG) principles into their corporate responsibility efforts. The guidelines emphasize high-standard social responsibility, economic leadership, and alignment with China’s sustainable development goals.

