INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bdd3771c-18c2-5419-8ebd-ba6553091b04', 'China Corporate Sustainability Disclosure Guidelines - Basic Guidelines (Exposure', 'Corporate Sustainability Disclosure Guidelines - Basic Guidelines (Exposure Draft)', 'The guidelines aim to standardize and improve the quality of sustainability disclosures by enterprises in China, emphasizing their alignment with environmental, social, and governance (ESG) principles. The document provides a framework for disclosing risks, opportunities, and impacts related to sustainable development across the value chain. It outlines four thematic disclosure elements: governance, strategy, risk and opportunity management, and metrics and targets. Reporting entities are required to align sustainability disclosures with their financial statements and ensure comparability, verifiability, and understandability. The guidelines mandate materiality assessments for sustainability information and emphasize the importance of reliable data collection systems and internal controls. Disclosure is primarily targeted at key users such as investors, creditors, and governments, and aims to promote sustainable economic, social, and environmental development.', 'The guidelines aim to standardize and improve the quality of sustainability disclosures by enterprises in China, emphasizing their alignment with environmental, social, and governance (ESG) principles. The document provides a framework for disclosing risks, opportunities, and impacts related to sustainable development across the value chain. It outlines four thematic disclosure elements: governance, strategy, risk and opportunity management, and metrics and targets. Reporting entities are required to align sustainability disclosures with their financial statements and ensure comparability, verifiability, and understandability. The guidelines mandate materiality assessments for sustainability information and emphasize the importance of reliable data collection systems and internal controls. Disclosure is primarily targeted at key users such as investors, creditors, and governments, and aims to promote sustainable economic, social, and environmental development.', 'The guidelines aim to standardize and improve the quality of sustainability disclosures by enterprises in China, emphasizing their alignment with environmental, social, and governance (ESG) principles. The document provides a framework for disclosing risks, opportunities, and impacts related to sustainable development across the value chain. It outlines four thematic disclosure elements: governance, strategy, risk and opportunity management, and metrics and targets. Reporting entities are required to align sustainability disclosures with their financial statements and ensure comparability, verifiability, and understandability. The guidelines mandate materiality assessments for sustainability information and emphasize the importance of reliable data collection systems and internal controls. Disclosure is primarily targeted at key users such as investors, creditors, and governments, and aims to promote sustainable economic, social, and environmental development.', 'China', 'climate', 'in_force', '2024-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_92', ARRAY['guidance_frameworks', 'sdg7', 'sdg16', 'disclosure', 'china', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9b76f1e5-3c1a-5b36-ac01-9d660c845145', 'China Corporate Sustainable Disclosure Standards – Basic Standards (Trial)', 'Corporate Sustainable Disclosure Standards – Basic Standards (Trial) Chapter 1 General Provisions', 'The Corporate Sustainable Disclosure Standards – Basic Standards (Trial) in China aim to regulate sustainable information disclosure by businesses to ensure quality and transparency. The policy targets investors, creditors, government agencies, and other stakeholders, emphasizing reliability, relevance, comparability, and verifiability of disclosed sustainability information.', 'The Corporate Sustainable Disclosure Standards – Basic Standards (Trial) in China aim to regulate sustainable information disclosure by businesses to ensure quality and transparency. The policy targets investors, creditors, government agencies, and other stakeholders, emphasizing reliability, relevance, comparability, and verifiability of disclosed sustainability information.', 'The Corporate Sustainable Disclosure Standards – Basic Standards (Trial) in China aim to regulate sustainable information disclosure by businesses to ensure quality and transparency. The policy targets investors, creditors, government agencies, and other stakeholders, emphasizing reliability, relevance, comparability, and verifiability of disclosed sustainability information.', 'China', 'governance', 'in_force', '2024-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_93', ARRAY['voluntary_frameworks', 'sdg16', 'china', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d170e19b-1166-524e-887d-9e97648d3adb', 'China Guide No.13 for Self-Regulatory Supervision on ListedCompanies', 'Guide No.13 for Self-Regulatory Supervision on ListedCompanies of the SSE STAR Market—Compilation of Sustainable Development Reports', 'This policy document outlines guidelines for self-regulatory supervision on sustainable development reporting for listed companies in China''s SSE STAR Market. It focuses on assessing pollutant emission-related risks and opportunities, calculating emissions, and disclosing key items. The target audience includes listed companies aiming to standardize sustainability reporting.', 'This policy document outlines guidelines for self-regulatory supervision on sustainable development reporting for listed companies in China''s SSE STAR Market. It focuses on assessing pollutant emission-related risks and opportunities, calculating emissions, and disclosing key items. The target audience includes listed companies aiming to standardize sustainability reporting.', 'This policy document outlines guidelines for self-regulatory supervision on sustainable development reporting for listed companies in China''s SSE STAR Market. It focuses on assessing pollutant emission-related risks and opportunities, calculating emissions, and disclosing key items. The target audience includes listed companies aiming to standardize sustainability reporting.', 'China', 'climate', 'in_force', '2024-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_94', ARRAY['china', 'mandatory', 'mandatory_regulations', 'sdg13']::text[]) ON CONFLICT (id) DO NOTHING;
