INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08f7e682-4c7d-52dc-87e2-163a17ca96f1', 'China Self-Regulatory Guidelines for Companies Listed on ShenzhenStock Exchange—Sustainability', 'Self-Regulatory Guidelines No. 17 for Companies Listed on ShenzhenStock Exchange—Sustainability Report (For Trial Implementation)', 'The policy document "Self-Regulatory Guidelines No. 17 for Companies Listed on Shenzhen Stock Exchange—Sustainability Report" aims to regulate sustainability information disclosure by listed companies in China. It requires integrating sustainability into business strategies and activities, publishing annual sustainability reports, and targets SZSE-listed companies to promote sustainable development and transparency.', 'The policy document "Self-Regulatory Guidelines No. 17 for Companies Listed on Shenzhen Stock Exchange—Sustainability Report" aims to regulate sustainability information disclosure by listed companies in China. It requires integrating sustainability into business strategies and activities, publishing annual sustainability reports, and targets SZSE-listed companies to promote sustainable development and transparency.', 'The policy document "Self-Regulatory Guidelines No. 17 for Companies Listed on Shenzhen Stock Exchange—Sustainability Report" aims to regulate sustainability information disclosure by listed companies in China. It requires integrating sustainability into business strategies and activities, publishing annual sustainability reports, and targets SZSE-listed companies to promote sustainable development and transparency.', 'China', 'climate', 'in_force', '2024-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_96', ARRAY['sdg16', 'china', 'voluntary', 'guidance_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('10fb4d62-6c55-5170-acf3-5cc75d4b03dd', 'China Continuous Supervisory Guidelines for Companies ListedonBeijing Stock Exchange—Sustainability', 'Continuous Supervisory Guidelines No. 11 for Companies ListedonBeijing Stock Exchange—Sustainability Report (For Trial Implementation)', 'The document outlines guidelines for Beijing Stock Exchange-listed companies to publish Sustainability Reports, promoting sustainability, governance, and social responsibility. Companies must disclose information accurately, comply with reporting standards, and continuously improve disclosure quality. The target audience is listed companies aiming for high-quality development and positive societal impact.', 'The document outlines guidelines for Beijing Stock Exchange-listed companies to publish Sustainability Reports, promoting sustainability, governance, and social responsibility. Companies must disclose information accurately, comply with reporting standards, and continuously improve disclosure quality. The target audience is listed companies aiming for high-quality development and positive societal impact.', 'The document outlines guidelines for Beijing Stock Exchange-listed companies to publish Sustainability Reports, promoting sustainability, governance, and social responsibility. Companies must disclose information accurately, comply with reporting standards, and continuously improve disclosure quality. The target audience is listed companies aiming for high-quality development and positive societal impact.', 'China', 'climate', 'in_force', '2024-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_97', ARRAY['sdg16', 'china', 'voluntary', 'guidance_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('84d613dd-7e71-5c9c-a26b-34b8f06c3f03', 'China Green Finance Guidelines for the Banking and Insurance', 'Green Finance Guidelines for the Banking and Insurance Sectors (银行业保险业绿色金融指引)', 'The Green Finance Guidelines for the Banking and Insurance Sectors, issued by the China Banking and Insurance Regulatory Commission (CBIRC), establish a comprehensive framework to promote green, low-carbon, and sustainable finance in China''s banking and insurance sectors. The guidelines aim to align financial institutions with China’s carbon neutrality goals, enhance environmental and social risk management, and increase transparency in green finance activities.

Key aspects include:

Scope and Coverage:
Applies to policy banks, commercial banks, rural credit cooperatives, insurance companies, and asset management firms.
Encourages non-bank financial institutions to adopt similar principles.
Strategic Integration:
Banks and insurers must incorporate green finance into business strategy and establish governance structures for sustainability.
Financial institutions must prioritize low-carbon and circular economy projects while mitigating environmental and social risks.
Risk Management:
Institutions must evaluate the environmental, social, and governance (ESG) risks of borrowers, investment projects, and insured clients.
High-risk sectors (e.g., coal, steel, chemicals) require enhanced due diligence and risk mitigation measures.
Sustainable Investment and Lending:
Banks must adjust loan approval policies to support clean energy, carbon reduction, and green technology projects.
Insurers must develop climate risk insurance products and enhance risk assessment tools for environmental hazards.
Transparency and Disclosure:
Financial institutions must publicly disclose green finance policies, ESG risk management strategies, and sustainability performance.
Third-party verification is encouraged to improve credibility.
Regulatory Oversight:
The CBIRC will conduct regular audits and assessments to ensure compliance.
Institutions failing to meet green finance standards may face regulatory penalties.', 'The Green Finance Guidelines for the Banking and Insurance Sectors, issued by the China Banking and Insurance Regulatory Commission (CBIRC), establish a comprehensive framework to promote green, low-carbon, and sustainable finance in China''s banking and insurance sectors. The guidelines aim to align financial institutions with China’s carbon neutrality goals, enhance environmental and social risk management, and increase transparency in green finance activities.

