INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c4d920a1-8572-50cc-adf1-544da98d2326', 'China Measures for the Administration of Information Disclosure', 'Measures for the Administration of Information Disclosure of Listed Companies (Revised Draft) (Draft for Comments)', 'The policy titled "Measures for the Administration of Information Disclosure of Listed Companies" outlines comprehensive requirements for listed companies in China to ensure transparency and accountability in their information disclosures. Developed under the oversight of the China Securities Regulatory Commission (CSRC), the policy mandates that disclosures be truthful, accurate, complete, timely, and fair. The measures aim to enhance investor protection and prevent malpractices such as insider trading and market manipulation. Key requirements include periodic reporting (annual, interim, and quarterly), immediate disclosure of significant events, and adherence to strict formats and approval processes for reports. The policy also addresses responsibilities of company directors, supervisors, and senior management to ensure compliance, providing mechanisms for supervision, legal accountability, and penalties for violations. Special provisions exist for disclosures in foreign markets, emphasizing consistency with domestic disclosures.

The policy''s ultimate goal is to strengthen the governance and operational transparency of listed companies, thereby promoting stability and confidence in China''s capital markets.', 'The policy titled "Measures for the Administration of Information Disclosure of Listed Companies" outlines comprehensive requirements for listed companies in China to ensure transparency and accountability in their information disclosures. Developed under the oversight of the China Securities Regulatory Commission (CSRC), the policy mandates that disclosures be truthful, accurate, complete, timely, and fair. The measures aim to enhance investor protection and prevent malpractices such as insider trading and market manipulation. Key requirements include periodic reporting (annual, interim, and quarterly), immediate disclosure of significant events, and adherence to strict formats and approval processes for reports. The policy also addresses responsibilities of company directors, supervisors, and senior management to ensure compliance, providing mechanisms for supervision, legal accountability, and penalties for violations. Special provisions exist for disclosures in foreign markets, emphasizing consistency with domestic disclosures.

The policy''s ultimate goal is to strengthen the governance and operational transparency of listed companies, thereby promoting stability and confidence in China''s capital markets.', 'The policy titled "Measures for the Administration of Information Disclosure of Listed Companies" outlines comprehensive requirements for listed companies in China to ensure transparency and accountability in their information disclosures. Developed under the oversight of the China Securities Regulatory Commission (CSRC), the policy mandates that disclosures be truthful, accurate, complete, timely, and fair. The measures aim to enhance investor protection and prevent malpractices such as insider trading and market manipulation. Key requirements include periodic reporting (annual, interim, and quarterly), immediate disclosure of significant events, and adherence to strict formats and approval processes for reports. The policy also addresses responsibilities of company directors, supervisors, and senior management to ensure compliance, providing mechanisms for supervision, legal accountability, and penalties for violations. Special provisions exist for disclosures in foreign markets, emphasizing consistency with domestic disclosures.

The policy''s ultimate goal is to strengthen the governance and operational transparency of listed companies, thereby promoting stability and confidence in China''s capital markets.', 'China', 'climate', 'in_force', '2021-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_24', ARRAY['sdg14', 'regulations', 'china', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('884fb356-e916-5c7c-a9cc-84f3644c2635', 'China Green Bond Endorsed Projects Catalogue', 'Green Bond Endorsed Projects Catalogue', 'The Green Bond Endorsed Projects Catalogue (2021 Edition) provides updated guidelines for the classification of projects eligible for green bond financing in China. The catalogue is a key policy instrument for aligning green finance with China’s environmental and climate goals, including achieving carbon neutrality by 2060. It outlines specific criteria for project eligibility, ensuring consistency with international green finance standards while addressing domestic priorities.

Key updates in the 2021 edition include the exclusion of projects related to clean coal technology, reflecting a shift toward stricter green definitions. Eligible categories encompass renewable energy, energy efficiency, pollution prevention and control, resource conservation, and climate adaptation. Projects must demonstrate clear environmental benefits, supported by measurable outcomes and third-party verification. The catalogue aims to mobilize capital toward sustainable development by providing investors with transparent criteria for green investments.

The document also aligns with international frameworks, such as the EU Taxonomy for Sustainable Activities, facilitating cross-border green finance initiatives. By promoting transparency and consistency, it strengthens investor confidence and accelerates the growth of China’s green bond market.', 'The Green Bond Endorsed Projects Catalogue (2021 Edition) provides updated guidelines for the classification of projects eligible for green bond financing in China. The catalogue is a key policy instrument for aligning green finance with China’s environmental and climate goals, including achieving carbon neutrality by 2060. It outlines specific criteria for project eligibility, ensuring consistency with international green finance standards while addressing domestic priorities.

