INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4f3c79bf-d50d-5e8f-b55d-3665fa388146', 'China Green Bond Issuance', 'Guidelines for Green Bond Issuance', 'These guidelines set out to further promote green development and facilitate the adjustment and optimisation of economic structure and the accelerated transformation of the mode of development.', 'These guidelines set out to further promote green development and facilitate the adjustment and optimisation of economic structure and the accelerated transformation of the mode of development.', 'These guidelines set out to further promote green development and facilitate the adjustment and optimisation of economic structure and the accelerated transformation of the mode of development.', 'China', 'climate', 'in_force', '2015-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_28', ARRAY['guidance_frameworks', 'sdg13', 'sdg2', 'sdg7', 'china', 'sdg6', 'sdg12', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d26aaf01-7937-5f02-a6de-dca36677522e', 'People''s Bank of China Announcement [2015]', 'The People''s Bank of China Announcement No. 39 [2015]', 'This Announcement aims to accelerate ecological civilization development, guide financial institutions to serve green development, promote economic restructuring and upgrading, and drive transformation of economic development pattern.', 'This Announcement aims to accelerate ecological civilization development, guide financial institutions to serve green development, promote economic restructuring and upgrading, and drive transformation of economic development pattern.', 'This Announcement aims to accelerate ecological civilization development, guide financial institutions to serve green development, promote economic restructuring and upgrading, and drive transformation of economic development pattern.', 'China', 'climate', 'in_force', '2015-01-01'::date, 'China', 'https://www.carrotsandsticks.org/policies/33_3', ARRAY['sdg7', 'china', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
